package com.coffeeshop.service;
import com.coffeeshop.dto.TableManagementCommands;import com.coffeeshop.model.TableManagementModels;import com.coffeeshop.repository.TableManagementRepository;import java.util.*;
public final class TableManagementService {private static final Set<String> TABLE_STATES=Set.of("AVAILABLE","OCCUPIED","RESERVED","OUT_OF_SERVICE");private static final Set<String> RESERVATION_STATES=Set.of("PENDING","CONFIRMED","SEATED","COMPLETED","CANCELLED","NO_SHOW");private final TableManagementRepository repository;public TableManagementService(TableManagementRepository r){repository=Objects.requireNonNull(r);}public List<TableManagementModels.CafeTable>tables(){return repository.tables();}public List<TableManagementModels.Reservation>reservations(){return repository.reservations();}public long saveTable(TableManagementCommands.SaveTable q){if(q==null)throw new IllegalArgumentException("Table details are required.");String code=required(q.code(),30,"Table code");String name=required(q.name(),100,"Table name");if(q.capacity()<=0)throw new IllegalArgumentException("Capacity must be positive.");if(!TABLE_STATES.contains(q.status()))throw new IllegalArgumentException("Select a valid table status.");if(q.displayOrder()<0)throw new IllegalArgumentException("Display order cannot be negative.");if(!q.active()&&busy(q.status()))throw new IllegalStateException("Occupied or reserved tables cannot be deactivated.");version(q.id(),q.rowVersion());return repository.saveTable(new TableManagementCommands.SaveTable(q.id(),code,name,q.capacity(),q.status(),q.displayOrder(),q.active(),q.rowVersion()));}public void setActive(TableManagementModels.CafeTable t,boolean active){Objects.requireNonNull(t);if(!active&&busy(t.status()))throw new IllegalStateException("Occupied or reserved tables cannot be deactivated.");repository.setTableActive(t.id(),active,t.rowVersion());}public long saveReservation(TableManagementCommands.SaveReservation q){if(q==null)throw new IllegalArgumentException("Reservation details are required.");if(q.tableId()<=0)throw new IllegalArgumentException("Select a table.");String guest=required(q.guestName(),200,"Guest name");if(q.startsAt()==null)throw new IllegalArgumentException("Reservation time is required.");if(q.partySize()<=0)throw new IllegalArgumentException("Party size must be positive.");if(!RESERVATION_STATES.contains(q.status()))throw new IllegalArgumentException("Select a valid reservation status.");version(q.id(),q.rowVersion());return repository.saveReservation(new TableManagementCommands.SaveReservation(q.id(),q.tableId(),q.customerId(),guest,optional(q.phone(),30),optional(q.email(),254),q.startsAt(),q.partySize(),q.status(),optional(q.notes(),1000),q.rowVersion()));}private static boolean busy(String status){return "OCCUPIED".equals(status)||"RESERVED".equals(status);}private static String required(String v,int max,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>max)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int max){return v==null||v.isBlank()?null:required(v,max,"Value");}private static void version(Long id,byte[] v){if(id!=null&&(v==null||v.length==0))throw new IllegalArgumentException("Refresh this record and try again.");}}
